// spec: .qa/e2e/specs/navigation.md (1.1)
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

const TABS: Array<[string, RegExp]> = [
  ['ילדים', /\/children/],
  ['היסטוריה', /\/history/],
  ['חשבון', /\/account/],
  ['בית', /\/home/],
  ['היסטוריה', /\/history/],
  ['ילדים', /\/children/],
];
const ALL = ['בית', 'ילדים', 'היסטוריה', 'חשבון'];

test.describe('Навигация — таб-бар', () => {
  test('Таб-бар: в каждый момент активна только текущая вкладка #fb3b8d53 @iphone @prod-safe', async ({ page }) => {
    // 1. /home, таб-бар из 4 вкладок
    await page.goto('/home');
    const tabs = page.getByRole('tab').filter({ visible: true });
    await expect(tabs).toHaveCount(4);
    for (const name of ALL) await expect(page.getByRole('tab', { name }).filter({ visible: true })).toBeVisible();
    await expect(page.getByRole('tab', { name: 'בית' }).filter({ visible: true })).toHaveAttribute('aria-selected', 'true');

    // 2. Нажимать вкладки по очереди; после каждого нажатия — URL вкладки и ровно одна выбранная
    for (const [name, url] of TABS) {
      await page.getByRole('tab', { name }).filter({ visible: true }).click();
      await expect(page).toHaveURL(url);
      await expect(page.getByRole('tab', { name }).filter({ visible: true })).toHaveAttribute('aria-selected', 'true');
      for (const other of ALL.filter((n) => n !== name)) {
        await expect(page.getByRole('tab', { name: other }).filter({ visible: true })).not.toHaveAttribute('aria-selected', 'true');
      }
      await expect(page.getByRole('tab', { selected: true }).filter({ visible: true })).toHaveCount(1);
    }
  });
});
